use xiom.io;

use xiom.string;
fn generate_password(length: Int, include_digits: Bool, include_symbols: Bool) -> Str {
  let mut pool = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
  if include_digits { pool = string.str_concat(pool, "0123456789"); };
  if include_symbols { pool = string.str_concat(pool, "!@#$%^&*"); };

  let mut password = "";
  let mut state = 12345;
  let mut i = 0;
  while i < length {
    state = (state * 1103515245 + 12345) % 2147483648;
    let idx = state % pool.len();
    password = string.str_concat(password, string.from_char(pool.get(idx).unwrap()));
    i += 1;
  };
  password
}

fn main() -> Int {
  io.println(generate_password(8, false, false));
  io.println(generate_password(10, true, false));
  io.println(generate_password(12, true, true));
  return 0;
}
